<div class="card-header"><div><h2>Permissions</h2><p><span data-permission-selected-count><?=count($selected)?></span> selected. Search and bulk-select by module.</p></div><div class="toolbar-actions"><button type="button" class="btn btn-secondary" data-permission-all>Select all</button><button type="button" class="btn btn-secondary" data-permission-none>Clear all</button><button type="button" class="btn btn-secondary" data-permission-toggle>Invert</button></div></div><div class="rbac-permission-tools"><label class="field rbac-search"><span>Search permissions</span><input type="search" data-permission-search placeholder="Search by name or code"></label><div class="rbac-module-filters"><button type="button" class="btn btn-secondary is-active" data-permission-module="all">All</button><?php $mods=[];foreach($permissions as $p){$code=(string)($p['code']??'');$mod=strtok($code,'.');if($mod!=='')$mods[$mod]=true;}foreach(array_keys($mods) as $mod):?><button type="button" class="btn btn-secondary" data-permission-module="<?=e($mod)?>"><?=e(ucwords(str_replace('_',' ',$mod)))?></button><?php endforeach;?></div></div>
